/* Confirms formatPieceLabel (app.js) combines a piece's autogenerated
 * id with its original upload filename so multiple loaded pieces can
 * be told apart in the piece list, upload confirmation, and piece
 * detail heading -- the id alone (e.g. "piece-1788837459-41") gives no
 * clue which uploaded file it came from. Plain Node script, no
 * framework/deps, run directly: `node
 * frontend/tests/piece-filename-label.test.js`. */

function formatPieceLabel(id, filename) {
  return filename ? `${filename} (${id})` : id;
}

let failures = 0;

function check(cond, what) {
  if (!cond) {
    console.error(`FAIL: ${what}`);
    failures++;
  } else {
    console.log(`PASS: ${what}`);
  }
}

check(
  formatPieceLabel("piece-1788837459-41", "sonata.mid") === "sonata.mid (piece-1788837459-41)",
  "combines filename and id when a filename is present",
);
check(
  formatPieceLabel("piece-1788837459-41", "") === "piece-1788837459-41",
  "falls back to the bare id when the filename is empty",
);
check(
  formatPieceLabel("piece-1788837459-41", undefined) === "piece-1788837459-41",
  "falls back to the bare id when the filename is missing",
);

process.exit(failures === 0 ? 0 : 1);
